```typescript
import { create } from 'zustand';

interface Dispute {
  id: string;
  orderId: string;
  buyerId: string;
  sellerId: string;
  reason: string;
  description: string;
  status: 'open' | 'assigned' | 'resolved' | 'closed';
  createdAt: string;
  assignedTo?: string;
}

interface DisputeStore {
  availableDisputes: Dispute[];
  assignedDisputes: Dispute[];
  isLoading: boolean;
  fetchAvailableDisputes: () => Promise<void>;
  fetchAssignedDisputes: () => Promise<void>;
  assignDispute: (disputeId: string) => Promise<void>;
  resolveDispute: (disputeId: string, decision: 'buyer' | 'seller') => Promise<void>;
}

export const useDisputeStore = create<DisputeStore>((set, get) => ({
  availableDisputes: [],
  assignedDisputes: [],
  isLoading: false,

  fetchAvailableDisputes: async () => {
    set({ isLoading: true });
    try {
      const response = await api.get('/disputes/available');
      set({ availableDisputes: response.data, isLoading: false });
    } catch (error) {
      set({ isLoading: false });
      console.error('Failed to fetch available disputes:', error);
    }
  },

  fetchAssignedDisputes: async () => {
    set({ isLoading: true });
    try {
      const response = await api.get('/disputes/assigned');
      set({ assignedDisputes: response.data, isLoading: false });
    } catch (error) {
      set({ isLoading: false });
      console.error('Failed to fetch assigned disputes:', error);
    }
  },

  assignDispute: async (disputeId: string) => {
    try {
      await api.post(`/disputes/${disputeId}/assign`);
      // Actualiser les listes
      await get().fetchAvailableDisputes();
      await get().fetchAssignedDisputes();
    } catch (error) {
      console.error('Failed to assign dispute:', error);
    }
  },

  resolveDispute: async (disputeId: string, decision: 'buyer' | 'seller') => {
    try {
      await api.post(`/disputes/${disputeId}/resolve`, { decision });
      // Actualiser les listes
      await get().fetchAvailableDisputes();
      await get().fetchAssignedDisputes();
    } catch (error) {
      console.error('Failed to resolve dispute:', error);
    }
  },
}));
```

