```typescript
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Image, TouchableOpacity, TextInput, StyleSheet } from 'react-native';
import { useDisputeStore } from '../stores/disputeStore';
import { useChatStore } from '../stores/chatStore';

interface DisputeResolutionScreenProps {
  route: {
    params: {
      disputeId: string;
      orderId: string;
    };
  };
  navigation: any;
}

export const DisputeResolutionScreen: React.FC<DisputeResolutionScreenProps> = ({ route, navigation }) => {
  const { disputeId, orderId } = route.params;
  const [decisionComment, setDecisionComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const dispute = useDisputeStore(state => state.availableDisputes.find(d => d.id === disputeId));
  const messages = useChatStore(state => state.messages[orderId] || []);
  const resolveDispute = useDisputeStore(state => state.resolveDispute);

  const handleResolve = async (decision: 'buyer' | 'seller') => {
    if (!decisionComment.trim()) {
      alert('Veuillez ajouter un commentaire sur votre décision');
      return;
    }

    setIsSubmitting(true);
    try {
      await resolveDispute(disputeId, decision);
      navigation.goBack();
    } catch (error) {
      alert('Erreur lors de la résolution du litige');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <ScrollView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>Résolution du litige #{disputeId.slice(0, 8)}</Text>
        <Text style={styles.status}>Statut: {dispute?.status}</Text>
      </View>

      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Motif du litige</Text>
        <Text style={styles.reason}>{dispute?.reason}</Text>
        <Text style={styles.description}>{dispute?.description}</Text>
      </View>

      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Messages échangés</Text>
        {messages.map((message) => (
          <View key={message.id} style={styles.messageContainer}>
            <Text style={styles.messageSender}>{message.sender}</Text>
            <Text style={styles.messageContent}>{message.content}</Text>
          </View>
        ))}
      </View>

      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Preuves</Text>
        <ScrollView horizontal>
          {dispute?.evidence?.map((evidence: string, index: number) => (
            <Image key={index} source={{ uri: evidence }} style={styles.evidenceImage} />
          ))}
        </ScrollView>
      </View>

      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Décision</Text>
        <TextInput
          style={styles.commentInput}
          placeholder="Commentaire sur la décision"
          value={decisionComment}
          onChangeText={setDecisionComment}
          multiline
        />
        <View style={styles.decisionButtons}>
          <TouchableOpacity
            style={[styles.decisionButton, styles.buyerButton]}
            onPress={() => handleResolve('buyer')}
            disabled={isSubmitting}
          >
            <Text style={styles.buttonText}>Régler à l'acheteur</Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.decisionButton, styles.sellerButton]}
            onPress={() => handleResolve('seller')}
            disabled={isSubmitting}
          >
            <Text style={styles.buttonText}>Régler au vendeur</Text>
          </TouchableOpacity>
        </View>
      </View>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#F5F5F5', padding: 16 },
  header: { marginBottom: 16 },
  title: { fontSize: 20, fontWeight: 'bold' },
  status: { fontSize: 14, color: '#666', marginTop: 4 },
  section: { backgroundColor: '#FFF', borderRadius: 8, padding: 16, marginBottom: 12 },
  sectionTitle: { fontSize: 16, fontWeight: 'bold', marginBottom: 8 },
  reason: { fontSize: 14, fontWeight: '600', color: '#333' },
  description: { fontSize: 14, color: '#666', marginTop: 4 },
  messageContainer: { marginBottom: 8, padding: 8, backgroundColor: '#F0F0F0', borderRadius: 4 },
  messageSender: { fontSize: 12, fontWeight: 'bold', color: '#3B82F6' },
  messageContent: { fontSize: 14 },
  evidenceImage: { width: 100, height: 100, borderRadius: 8, marginRight: 8 },
  commentInput: { borderWidth: 1, borderColor: '#DDD', borderRadius: 8, padding: 12, minHeight: 80, textAlignVertical: 'top' },
  decisionButtons: { flexDirection: 'row', justifyContent: 'space-between', marginTop: 12 },
  decisionButton: { flex: 1, padding: 12, borderRadius: 8, alignItems: 'center', marginHorizontal: 4 },
  buyerButton: { backgroundColor: '#3B82F6' },
  sellerButton: { backgroundColor: '#10B981' },
  buttonText: { color: '#FFF', fontWeight: 'bold' },
});
